/**
 * Server-side SFTP proxy for the in-portal file manager.
 *
 * This is a plain (non-"use server") module so it can be imported by both the
 * server actions (lib/actions-files.ts) and the upload/download route handler.
 * It never runs in the browser — the customer's root credentials stay on the
 * server; the browser only ever talks to our own actions/route.
 *
 * Connection target is derived EXACTLY like the server detail page:
 *   - dedicated-IP servers connect to their own IP on port 22
 *   - NAT servers use PUBLIC_IP + the forwarded SSH port
 * Username is always "root"; password is `server.rootPassword`.
 *
 * SANDBOX: on staging (NXEON_SANDBOX=1) no real SSH connection is ever opened —
 * every op is backed by a small in-memory simulated filesystem so the whole
 * file-manager UX works end to end without a live VM.
 */
import SftpClient from "ssh2-sftp-client";
import { SANDBOX } from "./sandbox";
import { decryptSecret } from "./crypto-box";

/**
 * Resolve a server's plaintext root password, preferring the encrypted-at-rest
 * value and falling back to the legacy plaintext column for rows that predate
 * encryption. Every READ of a root password must go through this helper so both
 * shapes keep working transparently.
 */
export function serverRootPassword(
  server: { rootPassword: string | null; rootPasswordEnc?: string | null }
): string | null {
  return decryptSecret(server.rootPasswordEnc) ?? server.rootPassword;
}

/** The minimal shape of a Server we need to open a connection. */
export type SftpServer = {
  id: string;
  rootPassword: string | null;
  rootPasswordEnc?: string | null;
  sshPort: number | null;
  dedicatedIp?: { address: string } | null;
};

export type SftpEntry = {
  name: string;
  /** "d" directory, "-" file, "l" symlink, etc. (ssh2-sftp-client `type`). */
  type: string;
  isDirectory: boolean;
  size: number;
  /** Unix mtime in ms. */
  modifiedMs: number;
  /** Numeric permission bits (e.g. 0o644), or null if unknown. */
  mode: number | null;
};

export type SftpStat = {
  isDirectory: boolean;
  size: number;
  modifiedMs: number;
  mode: number | null;
};

const CONNECT_TIMEOUT_MS = 10_000;

/** Max length for any absolute path we accept from the client. */
export const MAX_PATH_LEN = 4096;
/** Max length for a single path segment (file/folder name). */
export const MAX_NAME_LEN = 255;

/**
 * Normalize + validate an absolute POSIX path coming from the browser. Rejects
 * relative paths, `..` traversal, NUL bytes, and over-long paths. Returns a
 * cleaned absolute path (collapsed slashes, resolved `.`), always starting with
 * "/". Throws on anything suspicious — callers surface the message.
 */
export function normalizePath(input: string): string {
  if (typeof input !== "string") throw new Error("Invalid path.");
  if (input.length > MAX_PATH_LEN) throw new Error("Path is too long.");
  if (input.includes("\0")) throw new Error("Invalid path.");
  if (!input.startsWith("/")) throw new Error("Path must be absolute.");

  const out: string[] = [];
  for (const part of input.split("/")) {
    if (part === "" || part === ".") continue;
    if (part === "..") throw new Error("Path traversal is not allowed.");
    if (part.length > MAX_NAME_LEN) throw new Error("A path segment is too long.");
    out.push(part);
  }
  return "/" + out.join("/");
}

/**
 * Validate a single new file/folder name — no slashes, no traversal, no NUL,
 * not "." or "..". Returns the name unchanged if valid.
 */
export function validateName(name: string): string {
  if (typeof name !== "string" || name.length === 0) throw new Error("A name is required.");
  if (name.length > MAX_NAME_LEN) throw new Error("Name is too long.");
  if (name.includes("/") || name.includes("\0")) throw new Error("Name contains invalid characters.");
  if (name === "." || name === "..") throw new Error("That name is not allowed.");
  return name;
}

/** Join a validated absolute dir with a validated name, re-normalizing. */
export function joinPath(dir: string, name: string): string {
  return normalizePath(`${dir}/${name}`);
}

/**
 * Fixed directory every browser→server upload lands in. Uploads are ALWAYS
 * written here under a sanitized basename — never at a client-chosen path — so
 * a hostile filename can only ever create a file inside this one dir. Lives in
 * this plain module (not the "use server" action file) so it can be imported
 * and unit-tested without pulling in the server-action graph.
 */
export const UPLOAD_DIR = "/root/nxeon-uploads";

/**
 * Reduce an arbitrary, client-supplied filename to a SAFE basename that can only
 * land inside {@link UPLOAD_DIR}. Strips every directory component (POSIX `/`
 * and Windows `\`) so `../../etc/passwd` or `C:\evil\x` collapse to their final

// AES-256-GCM secret box for BYOK (bring-your-own-key) storage.
// The encryption key is derived from AUTH_SECRET via scrypt, so encrypted
// values are only recoverable on a server that holds the same AUTH_SECRET.
// This is a plain server-side module (no "use server") — safe to import from
// server actions and the worker, never from client bundles.

import { createCipheriv, createDecipheriv, randomBytes, scryptSync } from "node:crypto";

/** Derive the 32-byte AES key from AUTH_SECRET. Throws if AUTH_SECRET is unset. */
function deriveKey(): Buffer {
  const secret = process.env.AUTH_SECRET;
  if (!secret || !secret.trim()) {
    throw new Error("AUTH_SECRET is not set — cannot encrypt/decrypt secrets");
  }
  return scryptSync(secret, "nxeon-byok", 32);
}

/**
 * Encrypt a plaintext secret. Returns "iv:tag:ciphertext" (all base64).
 * A fresh random 12-byte IV is used per call.
 */
export function encryptSecret(plain: string): string {
  const iv = randomBytes(12);
  const cipher = createCipheriv("aes-256-gcm", deriveKey(), iv);
  const enc = Buffer.concat([cipher.update(plain, "utf8"), cipher.final()]);
  const tag = cipher.getAuthTag();
  return [iv.toString("base64"), tag.toString("base64"), enc.toString("base64")].join(":");
}

/**
 * Decrypt a value produced by encryptSecret. Returns null on any problem
 * (missing input, malformed value, wrong key, tampered ciphertext) so callers
 * can safely fall back without leaking whether decryption failed vs. was absent.
 */
export function decryptSecret(enc: string | null | undefined): string | null {
  if (!enc) return null;
  try {
    const [ivB64, tagB64, dataB64] = enc.split(":");
    if (!ivB64 || !tagB64 || !dataB64) return null;
    const decipher = createDecipheriv("aes-256-gcm", deriveKey(), Buffer.from(ivB64, "base64"));
    decipher.setAuthTag(Buffer.from(tagB64, "base64"));
    const dec = Buffer.concat([decipher.update(Buffer.from(dataB64, "base64")), decipher.final()]);
    return dec.toString("utf8");
  } catch {
    return null;
  }
}

/**
 * Shared, injection-safe SSH execution foundation for the customer control
 * panel (websites, databases, one-click apps, cron & services).
 *
 * This is a plain server-side module (NO "use server", no client imports) so it
 * can be used by both the inline read helpers (lib/cpanel-inline.ts) and the
 * worker executors (worker/websites|databases|apps|services.ts). It NEVER runs
 * in the browser — the customer's root credentials stay on the server.
 *
 * It mirrors the hardening in worker/migrate-real.ts on two axes:
 *
 *   1. STRICT ALLOWLIST VALIDATION. Every non-secret value that will be
 *      interpolated into a remote command MUST match a shell-inert allowlist
 *      (regexes below contain no quotes/spaces/metacharacters/newlines) or the
 *      operation FAILS. We reject — never sanitize. Callers validate up front
 *      with the `assert*` helpers so a bad value can never reach a shell.
 *
 *   2. SECRETS NEVER TOUCH A COMMAND STRING. Generated DB / app passwords are
 *      written to the far side via a command's STDIN (`execInput`) or an SFTP
 *      file — never as an argv token. Command strings reference only file paths
 *      or values that passed the allowlist.
 *
 * Connection target + root password derivation is identical to lib/sftp.ts and
 * worker/ssl.ts (dedicated IP → own IP:22, else PUBLIC_IP:sshPort; user root).
 */
import { Client, type ClientChannel } from "ssh2";
import { randomBytes } from "node:crypto";
import { connectionTarget, serverRootPassword, type SftpServer } from "./sftp";

// ---- Timeouts -------------------------------------------------------------
export const SSH_CONNECT_TIMEOUT_MS = 15_000;
/** Quick inline reads (list/status/snapshot) — kept short so a slow box can't
 *  wedge a page render. */
export const QUICK_TIMEOUT_MS = 12_000;
/** Small mutating commands (write a vhost, create a DB, edit crontab). */
export const SETUP_TIMEOUT_MS = 60_000;
/** Long installs (php-fpm, an engine, an app download). */
export const INSTALL_TIMEOUT_MS = Number(process.env.CPANEL_INSTALL_TIMEOUT_MS ?? 15 * 60_000);

// ---- Strict allowlist validators (throw on any violation) -----------------
// Every charset below is deliberately shell-inert.
export const DOMAIN_RE =
  /^(?=.{1,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,24}$/;
/** DB / DB-user identifier: letters, digits, underscore. */
export const IDENT_RE = /^[A-Za-z0-9_]{1,32}$/;
/** PHP version like 8.3 / 7.4. */
export const PHP_VERSION_RE = /^\d\.\d$/;
/** systemd unit name (bare service name we control from a fixed list). */
export const SERVICE_RE = /^[a-z0-9][a-z0-9_.-]{0,63}$/;
/** Absolute path with a safe charset, no traversal / double slash. */
export const PATH_RE = /^\/[A-Za-z0-9._/-]{1,255}$/;
/** A single crontab time field: digits, * , - , / and commas only. */
export const CRON_FIELD_RE = /^[0-9*,/-]{1,64}$/;
/** App slug from our fixed catalog. */
export const SLUG_RE = /^[a-z][a-z0-9-]{0,31}$/;

export function assert(cond: unknown, msg: string): asserts cond {
  if (!cond) throw new Error(msg);
}

export function assertDomain(d: string): void {
  assert(typeof d === "string" && DOMAIN_RE.test(d), `Unsupported domain: ${d}`);
}
export function assertIdent(v: string, what: string): void {
  assert(typeof v === "string" && IDENT_RE.test(v), `Unsupported ${what}: ${v}`);
}
export function assertPhp(v: string): void {
  assert(typeof v === "string" && PHP_VERSION_RE.test(v), `Unsupported PHP version: ${v}`);
}
export function assertService(v: string): void {
  assert(typeof v === "string" && SERVICE_RE.test(v), `Unsupported service: ${v}`);
}
export function assertPath(p: string): void {
  assert(
    typeof p === "string" && PATH_RE.test(p) && !p.includes("..") && !p.includes("//"),
    `Unsupported path: ${p}`
  );
}
export function assertSlug(s: string): void {
  assert(typeof s === "string" && SLUG_RE.test(s), `Unsupported app: ${s}`);
}

/**
 * Validate a 5-field cron schedule. Each field must match CRON_FIELD_RE, so the
 * whole expression is shell-inert (no metacharacters). Returns the normalized
 * single-spaced expression, or throws.
 */
export function assertCronSchedule(schedule: string): string {
  assert(typeof schedule === "string", "Invalid schedule.");
  const fields = schedule.trim().split(/\s+/);
  assert(fields.length === 5, "A cron schedule must have exactly 5 fields (min hour dom mon dow).");
  for (const f of fields) assert(CRON_FIELD_RE.test(f), `Unsupported cron field: ${f}`);
  return fields.join(" ");
}

/**
 * Defensive POSIX single-quote. Even allowlisted values are quoted when they are
 * interpolated, so a value that (against expectation) slipped through has no
 * shell effect. NEVER used for secrets — those go through STDIN/SFTP.
 */
export function shellQuote(s: string): string {
  return `'${String(s).replace(/'/g, `'\\''`)}'`;
}

// ---- SSH plumbing ---------------------------------------------------------

export type SshResult = { code: number | null; stdout: string; stderr: string };

/**
 * Run one command on an already-connected client, capturing output + exit code.
 * Rejects if the command exceeds `timeoutMs` (the channel is torn down so a hung
 * remote command can't wedge the worker/page).
 */
export function exec(conn: Client, command: string, timeoutMs: number): Promise<SshResult> {
  return new Promise((resolve, reject) => {
    conn.exec(command, (err, stream: ClientChannel) => {
      if (err) return reject(err);
      let stdout = "";
      let stderr = "";
      let settled = false;
      const timer = setTimeout(() => {
        if (settled) return;
        settled = true;
        try {
          stream.close();
        } catch {
          /* best effort */
        }
        reject(new Error(`Command timed out after ${Math.round(timeoutMs / 1000)}s`));
      }, timeoutMs);
      stream
        .on("close", (code: number | null) => {
          if (settled) return;
          settled = true;
          clearTimeout(timer);
          resolve({ code, stdout, stderr });
        })
        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
    });
  });
}

/**
 * Run a command and stream `input` into its STDIN — used to write a secret into
 * a file on the far side (`cat > file`) without the secret ever appearing as a
 * command-line argument. Mirrors worker/migrate-real.ts execRemoteInput.
 */
export function execInput(
  conn: Client,
  command: string,
  input: string,
  timeoutMs: number
): Promise<SshResult> {
  return new Promise((resolve, reject) => {
    conn.exec(command, (err, stream: ClientChannel) => {
      if (err) return reject(err);
      let stdout = "";
      let stderr = "";
      let settled = false;
      const timer = setTimeout(() => {
        if (settled) return;
        settled = true;
        try {
          stream.close();
        } catch {
          /* best effort */
        }
        reject(new Error(`Command timed out after ${Math.round(timeoutMs / 1000)}s`));
      }, timeoutMs);
      stream
        .on("close", (code: number | null) => {
          if (settled) return;
          settled = true;
          clearTimeout(timer);
          resolve({ code, stdout, stderr });
        })
        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
      stream.end(input);
    });
  });
}

/**
 * Open an SSH connection to a server, run `fn`, and ALWAYS end the connection.
 * Host/port/root-password derived exactly like lib/sftp. Throws a clear error if
 * the server isn't reachable yet or has no root password on record.
 *
 * Callers MUST guard SANDBOX before reaching here — no real SSH in staging.
 */
export async function withServerSsh<T>(
  server: SftpServer,
  fn: (conn: Client) => Promise<T>
): Promise<T> {
  const target = connectionTarget(server);
  if (!target) throw new Error("Server is not reachable yet — connection details are pending.");
  const password = serverRootPassword(server);
  if (!password) throw new Error("Server has no root password on record.");

  const conn = new Client();
  await new Promise<void>((resolve, reject) => {
    const timer = setTimeout(() => {
      try {
        conn.end();
      } catch {
        /* best effort */
      }
      reject(new Error(`SSH connect timed out after ${Math.round(SSH_CONNECT_TIMEOUT_MS / 1000)}s`));
    }, SSH_CONNECT_TIMEOUT_MS);
    conn
      .on("ready", () => {
        clearTimeout(timer);
        resolve();
      })
      .on("error", (e) => {
        clearTimeout(timer);
        reject(e instanceof Error ? e : new Error(String(e)));
      })
      .connect({
        host: target.host,
        port: target.port,
        username: "root",
        password,
        readyTimeout: SSH_CONNECT_TIMEOUT_MS,
      });
  });
  try {
    return await fn(conn);
  } finally {
    try {
      conn.end();
    } catch {
      /* best effort */
    }
  }
}

/**
 * Detect the package manager on the far side and return the install prefix, or
 * throw if none is supported. Fixed strings only — no user input.
 */
export async function pkgInstallPrefix(conn: Client): Promise<string> {
  const pm = await exec(
    conn,
    "if command -v apt-get >/dev/null 2>&1; then echo apt; " +
      "elif command -v dnf >/dev/null 2>&1; then echo dnf; " +
      "elif command -v yum >/dev/null 2>&1; then echo yum; else echo none; fi",
    QUICK_TIMEOUT_MS
  );
  const which = pm.stdout.trim();
  if (which === "apt") return "DEBIAN_FRONTEND=noninteractive apt-get install -y";
  if (which === "dnf") return "dnf install -y";
  if (which === "yum") return "yum install -y";
  throw new Error("No supported package manager (apt-get/dnf/yum) found on the server.");
}

/**
 * A generated secret is about to be embedded in a SQL/PHP string literal or a
 * credentials file (delivered over STDIN). `generateStrongPassword` is
 * alphanumeric by design; assert it, because a stray quote, colon or backslash
 * would break out of that literal — `.pgpass` and MySQL defaults files are both
 * colon/backslash sensitive.
 *
 * Lifted out of worker/apps.ts so worker/databases.ts can reuse it rather than
 * grow a second copy that drifts.
 */
export function assertInertSecret(secret: string, what: string): void {
  assert(/^[A-Za-z0-9]{8,128}$/.test(secret), `Unexpected ${what} shape — refusing to use it.`);
}

/** Trim remote output for a customer-facing error message. */
export function why(r: { stdout: string; stderr: string }): string {
  return (r.stderr || r.stdout).replace(/\s+/g, " ").trim().slice(0, 200);
}

/** A URL-safe generated password (no shell metacharacters, no ambiguity). */
export function generateStrongPassword(len = 20): string {
  return randomBytes(len * 2)
    .toString("base64url")
    .replace(/[-_]/g, "")
    .slice(0, len);
}

