// SAFE remote runner for the LIVE Soul Pilates box (51.79.226.200).
// Mirrors lib/sftp.ts + lib/ssh-exec.ts: fetch server by id, decrypt
// rootPasswordEnc via crypto-box, connect over ssh2. Password NEVER printed.
//
// HARD GUARD: before running the requested command it runs `hostname -I` on the
// far side and ABORTS unless it contains 51.79.226.200 — so a command can never
// land on the wrong host.
//
// Usage: node sp200-run.mjs <cmdfile>   (cmdfile = a file whose contents are the
// remote command; keeps quoting/heredocs intact). Reads stdin -> remote stdin.

import { readFileSync } from "node:fs";
import { createDecipheriv, scryptSync } from "node:crypto";
import { PrismaClient } from "@prisma/client";
import { Client } from "ssh2";
import "dotenv/config";

const SERVER_ID = "cmsc9l72y000ghl7iyd87u5ja";
const REQUIRED_IP = "51.79.226.200";

function deriveKey() {
  const secret = process.env.AUTH_SECRET;
  if (!secret || !secret.trim()) throw new Error("AUTH_SECRET not set");
  return scryptSync(secret, "nxeon-byok", 32);
}
function decryptSecret(enc) {
  if (!enc) return null;
  try {
    const [iv, tag, data] = enc.split(":");
    if (!iv || !tag || !data) return null;
    const d = createDecipheriv("aes-256-gcm", deriveKey(), Buffer.from(iv, "base64"));
    d.setAuthTag(Buffer.from(tag, "base64"));
    return Buffer.concat([d.update(Buffer.from(data, "base64")), d.final()]).toString("utf8");
  } catch {
    return null;
  }
}

function exec(conn, command, timeoutMs, stdin) {
  return new Promise((resolve, reject) => {
    conn.exec(command, (err, stream) => {
      if (err) return reject(err);
      let stdout = "", stderr = "", settled = false;
      const timer = setTimeout(() => {
        if (settled) return; settled = true;
        try { stream.close(); } catch {}
        reject(new Error(`timeout after ${Math.round(timeoutMs / 1000)}s`));
      }, timeoutMs);
      stream
        .on("close", (code) => { if (settled) return; settled = true; clearTimeout(timer); resolve({ code, stdout, stderr }); })
        .on("data", (d) => (stdout += d.toString("utf8")))
        .stderr.on("data", (d) => (stderr += d.toString("utf8")));
      if (stdin != null) stream.end(stdin);
    });
  });
}

async function main() {
  const cmdFile = process.argv[2];
  const timeoutMs = Number(process.argv[3] || 120000);
  if (!cmdFile) throw new Error("usage: node sp200-run.mjs <cmdfile> [timeoutMs]");
  const command = readFileSync(cmdFile, "utf8");
  const stdin = process.env.SP200_STDIN_FILE ? readFileSync(process.env.SP200_STDIN_FILE, "utf8") : null;

  const prisma = new PrismaClient();
  const server = await prisma.server.findUnique({
    where: { id: SERVER_ID },
    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
  });
  await prisma.$disconnect();
  if (!server) throw new Error("server not found: " + SERVER_ID);

  const password = decryptSecret(server.rootPasswordEnc) ?? server.rootPassword;
  if (!password) throw new Error("no root password on record");
  const dedicated = !!server.dedicatedIp;
  const host = dedicated ? server.dedicatedIp.address : process.env.PUBLIC_IP;
  const port = dedicated ? 22 : server.sshPort;
  if (!host || !port) throw new Error("no connection target");

  const conn = new Client();
  await new Promise((resolve, reject) => {
    const timer = setTimeout(() => { try { conn.end(); } catch {}; reject(new Error("connect timeout")); }, 15000);
    conn.on("ready", () => { clearTimeout(timer); resolve(); })
        .on("error", (e) => { clearTimeout(timer); reject(e); })
        .connect({ host, port, username: "root", password, readyTimeout: 15000 });
  });

  try {
    // HARD GUARD
    const guard = await exec(conn, "hostname -I", 15000);
    if (!guard.stdout.includes(REQUIRED_IP)) {
      throw new Error(`GUARD FAILED: remote hostname -I did not contain ${REQUIRED_IP}: ${JSON.stringify(guard.stdout)}`);
    }
    const r = await exec(conn, command, timeoutMs, stdin);
    process.stdout.write(r.stdout);
    if (r.stderr) process.stderr.write(r.stderr);
    process.exitCode = r.code ?? 0;
  } finally {
    try { conn.end(); } catch {}
  }
}

main().catch((e) => { console.error("ERR:", e.message); process.exit(1); });

// Download files from .200 to local via SFTP (read-only). Same creds path.
import { writeFileSync } from "node:fs";
import { createDecipheriv, scryptSync } from "node:crypto";
import { PrismaClient } from "@prisma/client";
import SftpClient from "ssh2-sftp-client";
import "dotenv/config";

const SERVER_ID = "cmsc9l72y000ghl7iyd87u5ja";
function deriveKey() { return scryptSync(process.env.AUTH_SECRET, "nxeon-byok", 32); }
function decryptSecret(enc) {
  if (!enc) return null;
  try { const [iv, tag, data] = enc.split(":");
    const d = createDecipheriv("aes-256-gcm", deriveKey(), Buffer.from(iv, "base64"));
    d.setAuthTag(Buffer.from(tag, "base64"));
    return Buffer.concat([d.update(Buffer.from(data, "base64")), d.final()]).toString("utf8");
  } catch { return null; }
}
// argv: pairs of remotePath localPath ...
const pairs = process.argv.slice(2);
const prisma = new PrismaClient();
const server = await prisma.server.findUnique({ where: { id: SERVER_ID }, select: { rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } } });
await prisma.$disconnect();
const password = decryptSecret(server.rootPasswordEnc) ?? server.rootPassword;
const host = server.dedicatedIp ? server.dedicatedIp.address : process.env.PUBLIC_IP;
