const sftp = new SftpClient();
await sftp.connect({ host, port, username: "root", password, readyTimeout: 15000 });
for (let i = 0; i < pairs.length; i += 2) {
  const buf = await sftp.get(pairs[i]);
  writeFileSync(pairs[i + 1], buf);
  console.log("got", pairs[i], "->", pairs[i + 1], buf.length, "bytes");
}
await sftp.end();

