using System.Globalization;
using MongoDB.Driver;
using SoulPilates.Core.DTOs;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Interfaces;
using SoulPilates.Infrastructure.Data;

namespace SoulPilates.Services;

/// <summary>
/// Mongo-backed analytics service. Owns the read-only aggregations that power
/// the admin dashboard's KPI cards (P3-S02 / SOW §15.1) and, in later slices,
/// the `/admin/analytics` page (P3-S03+).
///
/// <para>
/// Strict contract: <strong>every method on this service is read-only and
/// side-effect-free</strong>. Persisting from a dashboard load would corrupt
/// the long-tail history with phantom audit rows, so we never call
/// <c>InsertOneAsync</c> / <c>ReplaceOneAsync</c> / <c>UpdateManyAsync</c>
/// from anywhere in this file. Domain logic that needs to mutate state lives
/// in <see cref="IAccountingService"/> / <see cref="IPayrollService"/> instead.
/// </para>
/// </summary>
public class AnalyticsService : IAnalyticsService
{
    private readonly IMongoCollection<Invoice> _invoices;
    private readonly IMongoCollection<Attendance> _attendances;
    private readonly IMongoCollection<CalendarSession> _sessions;
    private readonly IMongoCollection<StaffPayable> _staffPayables;
    private readonly IMongoCollection<OwnerDistribution> _ownerDistributions;
    private readonly IMongoCollection<Client> _clients;
    private readonly IMongoCollection<Product> _products;
    private readonly IMongoCollection<Expense> _expenses;
    private readonly IMongoCollection<ClientPackage> _clientPackages;
    private readonly IMongoCollection<Payment> _payments;
    // Optional — used only by the dashboard Business Summary to fold instructor
    // commissions into profit. Null in unit tests that construct the service
    // with just a Mongo context.
    private readonly IPayrollService? _payroll;

    // Sentinel for an unset Mongo ObjectId reference. P2-S05 schema treats
    // `Invoice.ClientId` as non-nullable string, so drop-in / anonymous sales
    // either omit the field (deserialised as empty string) or store the
    // 24-zero ObjectId. Both are treated as "no human to rank" in Top Clients.
    private const string EmptyObjectId = "000000000000000000000000";

    // Attendance-status vocabularies, kept in one place so analytics agrees with
    // the rest of the domain. "ARRIVED" is a live synonym for "CHECKED_IN" (see
    // SessionCompletionBackgroundService + ReceptionistKpiService) — a session is
    // marked COMPLETED when it has at least one CHECKED_IN or ARRIVED attendee, so
    // analytics must treat both as "attended" or it undercounts every check-in,
    // occupancy and "class actually ran" metric.
    private static readonly string[] AttendedStatuses = { "CHECKED_IN", "ARRIVED" };
    // Active (non-cancelled, non-no-show) bookings: booked, or showed up.
    private static readonly string[] ActiveBookedStatuses = { "BOOKED", "CHECKED_IN", "ARRIVED" };

    public AnalyticsService(MongoDbContext dbContext, IPayrollService? payroll = null)
    {
        _payroll = payroll;
        _invoices = dbContext.GetCollection<Invoice>("Invoices");
        _attendances = dbContext.GetCollection<Attendance>("Attendances");
        _sessions = dbContext.GetCollection<CalendarSession>("CalendarSessions");
        _staffPayables = dbContext.GetCollection<StaffPayable>("StaffPayables");
        _ownerDistributions = dbContext.GetCollection<OwnerDistribution>("OwnerDistributions");
        _clients = dbContext.GetCollection<Client>("Clients");
        _products = dbContext.GetCollection<Product>("Products");
        _expenses = dbContext.GetCollection<Expense>("Expenses");
        _clientPackages = dbContext.GetCollection<ClientPackage>("ClientPackages");
        _payments = dbContext.GetCollection<Payment>("Payments");
    }

    public async Task<DashboardKpisDto> GetDashboardKpisAsync(DateTime asOfUtc)
    {
        // Single anchor: every "this month" / "this week" computation derives
        // from the same instant so the four KPIs are internally consistent
        // even if the call straddles a midnight UTC tick.
        var monthStart = new DateTime(asOfUtc.Year, asOfUtc.Month, 1, 0, 0, 0, DateTimeKind.Utc);
        var nextMonthStart = monthStart.AddMonths(1);
        var prevMonthStart = monthStart.AddMonths(-1);
        var weekStart = StartOfIsoWeek(asOfUtc);
        var weekEnd = weekStart.AddDays(7);          // Monday-inclusive, next-Monday-exclusive
        var thirtyDaysAgo = asOfUtc.AddDays(-30);

        var (revenueCurrent, revenuePrev, deltaPct, onlineFeesCurrent) = await ComputeRevenueAsync(monthStart, nextMonthStart, prevMonthStart);
        var activeClients = await CountActiveClientsAsync(thirtyDaysAgo);
        var classesThisWeek = await CountClassesThisWeekAsync(weekStart, weekEnd);
        var (payrollVnd, payrollLabel, payrollIsLatest) = await ComputePayrollEstimateAsync(asOfUtc.Year, asOfUtc.Month);

        return new DashboardKpisDto
        {
            MonthlyRevenueVnd = revenueCurrent,
            MonthlyRevenueDeltaPct = deltaPct,
            OnlineFeesReceivedVnd = onlineFeesCurrent,
            ActiveClients30d = activeClients,
            ClassesThisWeek = classesThisWeek,
            PayrollEstimateVnd = payrollVnd,
            PayrollEstimatePeriodLabel = payrollLabel,
            PayrollEstimateIsLatestComputed = payrollIsLatest,
            ComputedAt = DateTime.UtcNow,
        };
    }

