    public async Task<List<PaymentMethodDistributionDto>> GetPaymentMethodDistributionAsync(AnalyticsRangeQuery range)
    {
        if (range == null) throw new ArgumentNullException(nameof(range));

        // SPM — aggregate from the Payments collection (real per-invoice
        // {method, amount} tender splits) rather than the single
        // Attendance.PaymentMethod stamp. That stamp collapses a multi-tender
        // invoice (e.g. part CARD + part CASH, or a Stripe deposit + at-studio
        // balance) to ONE method and misattributes the whole booking's value to
        // it. Each Payment row is one real tender line, so both the counts and the
        // revenue now reflect how money actually came in. Return shape is
        // unchanged (Method / BookingCount / RevenueVnd / Share) — BookingCount is
        // now the number of payment lines for that method.
        var payments = await _payments
            .Find(Builders<Payment>.Filter.And(
                Builders<Payment>.Filter.Gte(p => p.PaymentDate, range.StartDate),
                Builders<Payment>.Filter.Lt(p => p.PaymentDate, range.EndDate)))
            .Project(p => new { p.PaymentMethod, p.AmountPaid })
            .ToListAsync();

        if (payments.Count == 0) return new List<PaymentMethodDistributionDto>();

        var total = payments.Count;
        return payments
            .GroupBy(p => string.IsNullOrWhiteSpace(p.PaymentMethod) ? "UNKNOWN" : p.PaymentMethod)
            .Select(g => new PaymentMethodDistributionDto
            {
                Method = g.Key,
                BookingCount = g.Count(),
                RevenueVnd = g.Sum(p => p.AmountPaid),
                Share = Math.Round((decimal)g.Count() / total, 4),
            })
            .OrderByDescending(r => r.BookingCount)
            .ToList();
    }
