    public async Task<List<InstructorPerformanceDto>> GetInstructorPerformanceAsync(AnalyticsRangeQuery range)
    {
        if (range == null) throw new ArgumentNullException(nameof(range));

        var sessions = await _sessions
            .Find(Builders<CalendarSession>.Filter.And(
                Builders<CalendarSession>.Filter.Gte(s => s.StartTime, range.StartDate),
                Builders<CalendarSession>.Filter.Lt(s => s.StartTime, range.EndDate),
                Builders<CalendarSession>.Filter.Eq(s => s.Status, "COMPLETED"),
                Builders<CalendarSession>.Filter.Eq(s => s.IsFreelance, false)))
            .ToListAsync();

        if (sessions.Count == 0) return new List<InstructorPerformanceDto>();

        var sessionIds = sessions.Select(s => s.Id).ToList();
        var attendances = await _attendances
            .Find(Builders<Attendance>.Filter.And(
                Builders<Attendance>.Filter.In(a => a.CalendarSessionId, sessionIds),
                Builders<Attendance>.Filter.In(a => a.Status, ActiveBookedStatuses)))
            .Project(a => new { a.CalendarSessionId, a.Status })
            .ToListAsync();

        var attBySession = attendances
            .Where(a => !string.IsNullOrEmpty(a.CalendarSessionId))
            .GroupBy(a => a.CalendarSessionId!)
            .ToDictionary(g => g.Key, g => g.ToList());

        // Only classes actually held with attendees: completed sessions that had
        // at least one checked-in attendee (matches the studio class-analytics rule).
        sessions = sessions
            .Where(s => s.Id != null && attBySession.TryGetValue(s.Id, out var a)
                        && a.Any(x => AttendedStatuses.Contains(x.Status)))
            .ToList();
        if (sessions.Count == 0) return new List<InstructorPerformanceDto>();

        // Packages purchased in the window, attributed (last-touch) to the
        // instructor whose class most recently converted the buyer.
        var packagesByInstructor = await ComputePackagesSoldByInstructorAsync(range);

        return sessions
            .GroupBy(s => s.InstructorId ?? "")
            .Select(g =>
            {
                var first = g.First();
                var totalBookings = 0;
                var totalCheckedIn = 0;
                foreach (var s in g)
                {
                    if (s.Id != null && attBySession.TryGetValue(s.Id, out var atts))
                    {
                        totalBookings += atts.Count;
                        totalCheckedIn += atts.Count(a => AttendedStatuses.Contains(a.Status));
                    }
                }
                var totalClasses = g.Count();
                var packagesSold = packagesByInstructor.GetValueOrDefault(g.Key, 0);
                return new InstructorPerformanceDto
                {
                    InstructorId = g.Key,
                    InstructorName = string.IsNullOrWhiteSpace(first.InstructorName) ? "(unassigned)" : first.InstructorName,
                    TotalClasses = totalClasses,
                    GroupClasses = g.Count(s => s.Format == "GROUP" || s.Format == "MAT"),
                    PrivateClasses = g.Count(s => s.Format == "PRIVATE" || s.Format == "DUO"),
                    TotalBookings = totalBookings,
                    TotalCheckedIn = totalCheckedIn,
                    PackagesSold = packagesSold,
                    ClassesPerPackage = packagesSold > 0
                        ? Math.Round((double)totalClasses / packagesSold, 2)
                        : (double?)null,
                };
            })
            .OrderByDescending(r => r.TotalClasses)
            .ToList();
    }
