    // ── State ──────────────────────────────────────────────────────────
    // Default = the CURRENT calendar month. On 2026-07-04 → July 2026.
    // (When picker is at 2026-07, range is [2026-07-01, 2026-08-01).)
    function defaultEndMonth() {
      const now = new Date();
      return { year: now.getFullYear(), month: now.getMonth() + 1 }; // 1..12, current month
    }

    const initial = defaultEndMonth();
    const state = {
      year: initial.year,
      month: initial.month, // 1..12 (the calendar month being analysed)
      format: "", // '' | 'GROUP' | 'PRIVATE' | 'DUO'
      // SPM-75 — optional "compare to" month for the Month Summary KPI strip.
      // null when no comparison is selected (page then behaves exactly as before).
      compareYear: null,
      compareMonth: null, // 1..12
    };

    // Derived: half-open [start, end) ISO date strings for a given calendar
    // month. Defaults to the primary (state) month so existing call sites are
    // unaffected; pass an explicit year/month for the comparison range.
    function rangeFor(year, month) {
      const start = `${year}-${String(month).padStart(2, "0")}-01`;
      // End-of-month exclusive = start of NEXT month.
      const ny = month === 12 ? year + 1 : year;
      const nm = month === 12 ? 1 : month + 1;
      const end = `${ny}-${String(nm).padStart(2, "0")}-01`;
      return { start, end };
    }

    function rangeFromState() {
      return rangeFor(state.year, state.month);
    }

    function periodLabel(year, month) {
      // "April 2026" form. Used in card subtitles for self-describing context.
      // Defaults to the primary (state) month for existing callers.
      const y = year ?? state.year;
      const m = month ?? state.month;
      const d = new Date(y, m - 1, 1);
      return d.toLocaleString("en-US", { month: "long", year: "numeric" });
    }

    // VND formatter — same shape as admin/index.astro for visual consistency.
    const fmtVnd = (n) =>
      `${Math.round(Number(n) || 0).toLocaleString("en-US")} ₫`;

    // Hour formatter — "6 AM" / "11 AM" / "5 PM" / "12 PM". Avoids "0 AM" pitfall.
    function fmtHour(h) {
      if (h === 0) return "12 AM";
      if (h === 12) return "12 PM";
      if (h < 12) return `${h} AM`;
      return `${h - 12} PM`;
    }

