    {
        asOfUtc = DateTime.SpecifyKind(asOfUtc, DateTimeKind.Utc);
        var nowLocal = asOfUtc + StudioUtcOffset;

        // Local calendar boundary → back to a UTC instant for the Mongo query.
        DateTime ToUtc(DateTime local) =>
            DateTime.SpecifyKind(local - StudioUtcOffset, DateTimeKind.Utc);

        var todayLocal = nowLocal.Date;
        var todayStart = ToUtc(todayLocal);
        var todayEnd = ToUtc(todayLocal.AddDays(1));
        var tomorrowStart = todayEnd;
        var tomorrowEnd = ToUtc(todayLocal.AddDays(2));

        // ISO week (Monday-anchored) containing the local "today".
        var dow = ((int)todayLocal.DayOfWeek + 6) % 7; // Mon=0 … Sun=6
        var weekMondayLocal = todayLocal.AddDays(-dow);
        var weekStart = ToUtc(weekMondayLocal);
        var weekEnd = ToUtc(weekMondayLocal.AddDays(7));

        var monthFirstLocal = new DateTime(todayLocal.Year, todayLocal.Month, 1, 0, 0, 0);
        var monthStart = ToUtc(monthFirstLocal);
        var monthEnd = ToUtc(monthFirstLocal.AddMonths(1));

        var windows = new (string Period, DateTime Start, DateTime End)[]
        {
            ("TODAY", todayStart, todayEnd),
            ("TOMORROW", tomorrowStart, tomorrowEnd),
            ("THIS_WEEK", weekStart, weekEnd),
            ("THIS_MONTH", monthStart, monthEnd),
        };

        RevenueForecastDto Empty()
        {
            RevenueForecastPeriodDto P(string name, DateTime s, DateTime e) =>
                new() { Period = name, WindowStartUtc = s, WindowEndUtc = e };
            return new RevenueForecastDto
            {
                Today = P("TODAY", todayStart, todayEnd),
                Tomorrow = P("TOMORROW", tomorrowStart, tomorrowEnd),
                ThisWeek = P("THIS_WEEK", weekStart, weekEnd),
                ThisMonth = P("THIS_MONTH", monthStart, monthEnd),
                ComputedAtUtc = DateTime.UtcNow,
            };
        }

