        // bound is max(windowStart, now). Load upcoming sessions from now until the
        // furthest window end so the week bucket stays complete even when it spills
        // past month-end.
        var loadUntil = windows.Max(w => w.End);
        if (loadUntil <= asOfUtc) return Empty();

        var sessions = await _sessions
            .Find(Builders<CalendarSession>.Filter.And(
                Builders<CalendarSession>.Filter.Gte(s => s.StartTime, asOfUtc),
                Builders<CalendarSession>.Filter.Lt(s => s.StartTime, loadUntil),
                Builders<CalendarSession>.Filter.Eq(s => s.Status, "SCHEDULED"),
                Builders<CalendarSession>.Filter.Eq(s => s.IsFreelance, false)))
            .Project(s => new
