            .Select(s => s.ClassBlueprintId!)
            .Distinct()
            .ToList();
        var blueprintPrice = new Dictionary<string, decimal>();
        if (needBlueprintPrice.Count > 0)
        {
            var bps = await _blueprints
                .Find(Builders<ClassBlueprint>.Filter.In(b => b.Id, needBlueprintPrice))
                .Project(b => new { b.Id, b.DropInPrice })
                .ToListAsync();
            foreach (var b in bps)
                if (!string.IsNullOrEmpty(b.Id)) blueprintPrice[b.Id!] = b.DropInPrice;
        }

        decimal PriceOfSession(string sessionId)
        {
            var s = sessionById[sessionId];
            if ((s.DropInPrice ?? 0m) > 0m) return s.DropInPrice!.Value;
            if (!string.IsNullOrEmpty(s.ClassBlueprintId)
