            .Where(b => !string.IsNullOrEmpty(b.CalendarSessionId)
                        && sessionById.ContainsKey(b.CalendarSessionId!))
            .OrderBy(b => sessionById[b.CalendarSessionId!].StartTime)
            .ToList();

        var acc = windows.ToDictionary(w => w.Period, _ => new RevenueForecastPeriodDto());
        foreach (var (period, _, _) in windows)
        {
            acc[period].Period = period;
        }

        foreach (var b in ordered)
        {
