            var startUtc = session.StartTime;
            var qty = b.Quantity <= 0 ? 1 : b.Quantity;
            var price = PriceOfSession(b.CalendarSessionId!);
            var bucket = CreditBucketForFormat(session.Format);

            // How many of this booking's seats are covered by a package credit.
            var explicitCredit = string.Equals(b.PaymentMethod, "PACKAGE_CREDIT", StringComparison.OrdinalIgnoreCase)
                                  || !string.IsNullOrEmpty(b.PackageInstanceId);

            int coveredSeats;
            var hasClient = !string.IsNullOrEmpty(b.ClientId)
                            && creditBalance.TryGetValue(b.ClientId!, out _);
            var available = 0;
            if (hasClient) creditBalance[b.ClientId!].TryGetValue(bucket, out available);

            if (explicitCredit)
            {
                // Already flagged to pay by credit → fully covered (already paid).
