                if (hasClient) creditBalance[b.ClientId!][bucket] = Math.Max(0, available - qty);
            }
            else
            {
                coveredSeats = Math.Min(available, qty);
                if (coveredSeats > 0) creditBalance[b.ClientId!][bucket] = available - coveredSeats;
