    // ── Show Rate: new vs recurring (card cmsj1mpq00018hljajup3qtb3) ──────────
    //
    // Show rate = attended ÷ booked over the selected period, where:
    //   • "booked"   = FINALIZED attendances whose session started in the window —
    //                  i.e. the class ran and the outcome is known: CHECKED_IN /
    //                  ARRIVED (attended) or NO_SHOW (booked-but-absent).
    //                  RESERVED / BOOKED (still in the future), CANCELLED,
    //                  LATE_CANCEL and RESCHEDULED are excluded — they never
    //                  reached a show/no-show verdict.
    //   • "attended" = CHECKED_IN / ARRIVED.
    //
    // NEW vs RECURRING is decided PER attendance from the client's history at the
    // time of that class:
    //   • NEW       = the client had NO prior attended (CHECKED_IN/ARRIVED) class
    //                 before this session's start — this is (among) their first
    //                 ever visit(s).
    //   • RECURRING = the client had ≥1 prior attended class before this session.
    // Anonymous rows (no ClientId / 24-zero id) are excluded — they can't be
    // attributed to a person's history.

    public async Task<ShowRateDto> GetShowRateAsync(AnalyticsRangeQuery range)
    {
        if (range == null) throw new ArgumentNullException(nameof(range));

        var result = new ShowRateDto
        {
            New = new ShowRateCohortDto { Cohort = "NEW" },
            Recurring = new ShowRateCohortDto { Cohort = "RECURRING" },
