        // has a start-time inside the range). We key attendances to these to get a
        // reliable class start-time for both the window filter and the "prior
        // attendance" comparison.
        var windowSessions = await _sessions
            .Find(Builders<CalendarSession>.Filter.And(
                Builders<CalendarSession>.Filter.Gte(s => s.StartTime, range.StartDate),
                Builders<CalendarSession>.Filter.Lt(s => s.StartTime, range.EndDate)))
            .Project(s => new { s.Id, s.StartTime })
            .ToListAsync();
        if (windowSessions.Count == 0) return result;

        var windowStartById = windowSessions
            .Where(s => !string.IsNullOrEmpty(s.Id))
