            var cohort = hasPrior ? result.Recurring : result.New;

            cohort.Booked += 1;
            if (AttendedStatuses.Contains(a.Status)) cohort.Attended += 1;
        }

        result.New.ShowRatePct = result.New.Booked > 0
            ? Math.Round((decimal)result.New.Attended / result.New.Booked * 100m, 1)
            : 0m;
        result.Recurring.ShowRatePct = result.Recurring.Booked > 0
            ? Math.Round((decimal)result.Recurring.Attended / result.Recurring.Booked * 100m, 1)
            : 0m;

        return result;
    }
}

