using System;

namespace SoulPilates.Core.DTOs;

/// <summary>
/// One window's revenue forecast from upcoming (still-to-come) bookings.
/// Amounts are VND. See <see cref="Interfaces.IAnalyticsService.GetRevenueForecastAsync"/>
/// for the credit-covered = 0 rule.
/// </summary>
public class RevenueForecastPeriodDto
{
    /// <summary>TODAY / TOMORROW / THIS_WEEK / THIS_MONTH.</summary>
    public string Period { get; set; } = string.Empty;

    /// <summary>Expected still-to-be-collected revenue (VND) from chargeable bookings in this window.</summary>
    public decimal ForecastVnd { get; set; }

    /// <summary>Active upcoming bookings (RESERVED/BOOKED) whose session starts in this window.</summary>
    public int TotalBookings { get; set; }

    /// <summary>Bookings that will be charged (drop-in / no covering credit) — these drive the forecast.</summary>
    public int ChargeableBookings { get; set; }

    /// <summary>Bookings already covered by a package credit for that class type — contribute 0.</summary>
    public int CreditCoveredBookings { get; set; }

    public DateTime WindowStartUtc { get; set; }
    public DateTime WindowEndUtc { get; set; }
}

/// <summary>
/// Forecasted revenue from upcoming bookings across the four studio-local windows.
/// </summary>
public class RevenueForecastDto
{
    public RevenueForecastPeriodDto Today { get; set; } = new();
    public RevenueForecastPeriodDto Tomorrow { get; set; } = new();
    public RevenueForecastPeriodDto ThisWeek { get; set; } = new();
    public RevenueForecastPeriodDto ThisMonth { get; set; } = new();
    public DateTime ComputedAtUtc { get; set; }
}

/// <summary>
/// Show-rate for one client cohort (NEW or RECURRING) over a period.
/// Show rate = <see cref="Attended"/> ÷ <see cref="Booked"/>.
/// </summary>
public class ShowRateCohortDto
{
    /// <summary>NEW or RECURRING.</summary>
    public string Cohort { get; set; } = string.Empty;

    /// <summary>Finalized attendances (attended + no-show) whose class ran in the window.</summary>
    public int Booked { get; set; }

    /// <summary>Attended = CHECKED_IN / ARRIVED.</summary>
    public int Attended { get; set; }

    /// <summary>Attended ÷ booked as a percentage (1 dp); 0 when the cohort had no finalized bookings.</summary>
    public decimal ShowRatePct { get; set; }
}

/// <summary>
/// Show-rate metrics split into NEW vs RECURRING clients for a date window.
/// </summary>
public class ShowRateDto
{
    public ShowRateCohortDto New { get; set; } = new() { Cohort = "NEW" };
    public ShowRateCohortDto Recurring { get; set; } = new() { Cohort = "RECURRING" };
    public DateTime RangeStartUtc { get; set; }
    public DateTime RangeEndUtc { get; set; }
}

