/// <summary>
/// Forecasted revenue from upcoming bookings for today / tomorrow / this week /
/// this month (studio-local windows), anchored on server <c>UtcNow</c>.
/// Bookings the client will pay for with a package credit contribute 0 (already
/// paid); only chargeable (drop-in / no covering credit) bookings count, at the
/// session's drop-in price. Snapshot semantics — independent of the month picker.
/// </summary>
[HttpGet("revenue-forecast")]
public async Task<IActionResult> GetRevenueForecast()
{
    var dto = await _analyticsService.GetRevenueForecastAsync(DateTime.UtcNow);
    return Ok(dto);
}

/// <summary>
/// Show-rate (attended ÷ booked) split into NEW vs RECURRING clients for
/// <c>[startDate, endDate)</c>. See
/// <see cref="IAnalyticsService.GetShowRateAsync"/> for the cohort + booked
/// definitions.
/// </summary>
[HttpGet("show-rate")]
public async Task<IActionResult> GetShowRate(
    [FromQuery] DateTime startDate,
    [FromQuery] DateTime endDate)
{
    var range = new AnalyticsRangeQuery
    {
        StartDate = DateTime.SpecifyKind(startDate, DateTimeKind.Utc),
        EndDate = DateTime.SpecifyKind(endDate, DateTimeKind.Utc),
    };
    var (ok, reason) = range.Validate();
    if (!ok) return BadRequest(new { error = reason });

    var dto = await _analyticsService.GetShowRateAsync(range);
    return Ok(dto);
}

/// <summary>
/// Monthly revenue vs expenses for the given year. Powers the admin
/// dashboard chart with live data (replaces hardcoded placeholders).
/// </summary>
[HttpGet("yearly-revenue-expense")]

// ── Revenue Forecast (card cmsj1j4ai0016hlja7ikbdbec) ──────────────
// Anchored on "now" (server UtcNow), NOT the month picker — this forecasts
// still-to-come bookings. Bookings a client will pay for with a package
// credit for that class type contribute 0 (already paid); only chargeable
// drop-ins count, at the session's drop-in price.
async function loadRevenueForecast() {
  try {
    const res = await fetch(`${API}/api/analytics/revenue-forecast`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const d = await res.json();
    const set = (id, p) => {
      const v = document.getElementById(id);
      const s = document.getElementById(id + "-sub");
      if (v) v.textContent = fmtVnd(p?.forecastVnd ?? 0);
      if (s) {
        const charge = p?.chargeableBookings ?? 0;
        const credit = p?.creditCoveredBookings ?? 0;
        s.textContent = `${charge} to charge · ${credit} on credit`;
      }
    };
    set("forecast-today", d.today);
    set("forecast-tomorrow", d.tomorrow);
    set("forecast-week", d.thisWeek);
    set("forecast-month", d.thisMonth);
  } catch (e) {
    console.warn("[analytics] revenue-forecast failed:", e);
  }
}

// ── Show Rate: new vs recurring (card cmsj1mpq00018hljajup3qtb3) ────
// NEW = client's first-ever visit (no prior attended class before the
// session). RECURRING = had a prior attended class. Show rate =
// attended (checked-in) ÷ booked (checked-in + no-show) for the period.
async function loadShowRate() {
  const { start, end } = rangeFromState();
  const sub = document.getElementById("showRateSubtitle");
  if (sub) sub.textContent = periodLabel();
  try {
    const res = await fetch(
      `${API}/api/analytics/show-rate?startDate=${start}&endDate=${end}`,
      { headers: { Authorization: `Bearer ${token}` } },
    );
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const d = await res.json();
    const pct = (n) => `${(Number(n) || 0).toFixed(1)}%`;
    const set = (id, c) => {
      const v = document.getElementById(id);
      const s = document.getElementById(id + "-sub");
      if (v) v.textContent = pct(c?.showRatePct ?? 0);
      if (s) s.textContent = `${c?.attended ?? 0} / ${c?.booked ?? 0} showed up`;
    };
    set("showrate-new", d.new);
    set("showrate-recurring", d.recurring);
  } catch (e) {
    console.warn("[analytics] show-rate failed:", e);
    if (sub) sub.textContent = "Unable to load";
  }
}

