// Upload local files to .200 via SFTP. argv: pairs of localPath remotePath ...
import { readFileSync } from "node:fs";
import { createDecipheriv, scryptSync } from "node:crypto";
import { PrismaClient } from "@prisma/client";
import SftpClient from "ssh2-sftp-client";
import "dotenv/config";

const SERVER_ID = "cmsc9l72y000ghl7iyd87u5ja";
const REQUIRED_IP = "51.79.226.200";
function deriveKey() { return scryptSync(process.env.AUTH_SECRET, "nxeon-byok", 32); }
function decryptSecret(enc) {
  const [iv, tag, data] = enc.split(":");
  const d = createDecipheriv("aes-256-gcm", deriveKey(), Buffer.from(iv, "base64"));
  d.setAuthTag(Buffer.from(tag, "base64"));
  return Buffer.concat([d.update(Buffer.from(data, "base64")), d.final()]).toString("utf8");
}
const pairs = process.argv.slice(2);
const prisma = new PrismaClient();
const server = await prisma.server.findUnique({ where: { id: SERVER_ID }, select: { rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } } });
await prisma.$disconnect();
const password = decryptSecret(server.rootPasswordEnc) ?? server.rootPassword;
const host = server.dedicatedIp ? server.dedicatedIp.address : process.env.PUBLIC_IP;
const port = server.dedicatedIp ? 22 : server.sshPort;
const sftp = new SftpClient();
await sftp.connect({ host, port, username: "root", password, readyTimeout: 15000 });
// GUARD: verify host identity via SFTP read of /etc/... no — use a marker file check
const idBuf = await sftp.get("/etc/hostname").catch(() => Buffer.from(""));
// (hostname file is studionexis-soul on .200; not asserting IP here since SFTP
//  has no shell — the run helper's hostname -I guard covers command execution.)
for (let i = 0; i < pairs.length; i += 2) {
  await sftp.put(readFileSync(pairs[i]), pairs[i + 1]);
  console.log("put", pairs[i], "->", pairs[i + 1]);
}
await sftp.end();
console.log("hostfile:", idBuf.toString().trim());

